-- Whole-day sessions no longer have a check-in grace period.
-- The app converts selected calendar dates to inclusive instants in APP_TIME_ZONE.
-- Preserve existing session schedules; editing them upgrades to whole-day dates.
CREATE OR REPLACE FUNCTION lms_private.session_checkin_grace() RETURNS interval
LANGUAGE sql IMMUTABLE SET search_path = '' AS $$ SELECT interval '0 minutes' $$;

-- Bring existing unrevoked tokens into line with the session bounds.
UPDATE lms.session_qr_tokens q
SET valid_from = s.starts_at, expires_at = s.ends_at
FROM lms.curriculum_sessions s
WHERE q.session_id = s.id AND q.revoked_at IS NULL;
